package com.shopsphere.dao;
import com.shopsphere.model.Product;
import com.shopsphere.util.DBConnection;
import java.math.BigDecimal;
import java.sql.*;
import java.util.*;
import java.util.logging.*;
public class ProductDAO {
    private static final Logger LOGGER = Logger.getLogger(ProductDAO.class.getName());
    public Product findById(Long id) { try (Connection c = DBConnection.getConnection(); PreparedStatement p = c.prepareStatement("SELECT p.*, c.name AS category_name, COALESCE(AVG(r.rating),0) AS avg_rating, COUNT(r.id) AS rev_count FROM products p JOIN categories c ON p.category_id=c.id LEFT JOIN reviews r ON p.id=r.product_id WHERE p.id=? GROUP BY p.id")) { p.setLong(1, id); try (ResultSet r = p.executeQuery()) { return r.next() ? mapRow(r) : null; } } catch (SQLException e) { return null; } }
    public List<Product> findFiltered(Integer catId, String key, BigDecimal minP, BigDecimal maxP, String sort, int off, int lim) { List<Product> l = new ArrayList<>(); StringBuilder sql = new StringBuilder("SELECT p.*, c.name AS category_name, COALESCE(AVG(r.rating),0) AS avg_rating, COUNT(r.id) AS rev_count FROM products p JOIN categories c ON p.category_id=c.id LEFT JOIN reviews r ON p.id=r.product_id WHERE p.status='ACTIVE' "); List<Object> par = new ArrayList<>(); if (catId != null && catId > 0) { sql.append("AND p.category_id=? "); par.add(catId); } if (key != null && !key.isBlank()) { sql.append("AND (LOWER(p.name) LIKE ? OR LOWER(p.brand) LIKE ?) "); String term = "%" + key.trim().toLowerCase() + "%"; par.add(term); par.add(term); } if (minP != null) { sql.append("AND p.price>=? "); par.add(minP); } if (maxP != null && maxP.compareTo(BigDecimal.ZERO) > 0) { sql.append("AND p.price<=? "); par.add(maxP); } sql.append("GROUP BY p.id "); if ("price_asc".equals(sort)) sql.append("ORDER BY p.price ASC "); else if ("price_desc".equals(sort)) sql.append("ORDER BY p.price DESC "); else sql.append("ORDER BY p.id DESC "); sql.append("LIMIT ? OFFSET ?"); par.add(lim); par.add(off); try (Connection c = DBConnection.getConnection(); PreparedStatement p = c.prepareStatement(sql.toString())) { for (int i = 0; i < par.size(); i++) p.setObject(i + 1, par.get(i)); try (ResultSet r = p.executeQuery()) { while (r.next()) l.add(mapRow(r)); } } catch (SQLException e) {} return l; }
    public int countFiltered(Integer catId, String key, BigDecimal minP, BigDecimal maxP) { StringBuilder sql = new StringBuilder("SELECT COUNT(DISTINCT p.id) FROM products p WHERE p.status='ACTIVE' "); List<Object> par = new ArrayList<>(); if (catId != null && catId > 0) { sql.append("AND p.category_id=? "); par.add(catId); } if (key != null && !key.isBlank()) { sql.append("AND (LOWER(p.name) LIKE ? OR LOWER(p.brand) LIKE ?) "); String term = "%" + key.trim().toLowerCase() + "%"; par.add(term); par.add(term); } try (Connection c = DBConnection.getConnection(); PreparedStatement p = c.prepareStatement(sql.toString())) { for (int i = 0; i < par.size(); i++) p.setObject(i + 1, par.get(i)); try (ResultSet r = p.executeQuery()) { if (r.next()) return r.getInt(1); } } catch (SQLException e) {} return 0; }
    public List<Product> findFeatured(int limit) { List<Product> l = new ArrayList<>(); try (Connection c = DBConnection.getConnection(); PreparedStatement p = c.prepareStatement("SELECT p.*, c.name AS category_name, 0 AS avg_rating, 0 AS rev_count FROM products p JOIN categories c ON p.category_id=c.id WHERE p.status='ACTIVE' AND p.stock>0 ORDER BY p.discount DESC LIMIT ?")) { p.setInt(1, limit); try (ResultSet r = p.executeQuery()) { while (r.next()) l.add(mapRow(r)); } } catch (SQLException e) {} return l; }
    public List<Product> findRelated(Long prodId, Integer catId, int limit) { List<Product> l = new ArrayList<>(); try (Connection c = DBConnection.getConnection(); PreparedStatement p = c.prepareStatement("SELECT p.*, c.name AS category_name, 0 AS avg_rating, 0 AS rev_count FROM products p JOIN categories c ON p.category_id=c.id WHERE p.status='ACTIVE' AND p.category_id=? AND p.id!=? LIMIT ?")) { p.setInt(1, catId); p.setLong(2, prodId); p.setInt(3, limit); try (ResultSet r = p.executeQuery()) { while (r.next()) l.add(mapRow(r)); } } catch (SQLException e) {} return l; }
    public List<Product> findAllForAdmin() { List<Product> l = new ArrayList<>(); try (Connection c = DBConnection.getConnection(); PreparedStatement p = c.prepareStatement("SELECT p.*, c.name AS category_name, 0 AS avg_rating, 0 AS rev_count FROM products p JOIN categories c ON p.category_id=c.id ORDER BY p.id DESC"); ResultSet r = p.executeQuery()) { while (r.next()) l.add(mapRow(r)); } catch (SQLException e) {} return l; }
    public boolean create(Product p) { try (Connection c = DBConnection.getConnection(); PreparedStatement ps = c.prepareStatement("INSERT INTO products (category_id,name,brand,description,price,discount,stock,image_url,status) VALUES (?,?,?,?,?,?,?,?,?)", Statement.RETURN_GENERATED_KEYS)) { ps.setInt(1, p.getCategoryId()); ps.setString(2, p.getName()); ps.setString(3, p.getBrand()); ps.setString(4, p.getDescription()); ps.setBigDecimal(5, p.getPrice()); ps.setBigDecimal(6, p.getDiscount()); ps.setInt(7, p.getStock()); ps.setString(8, p.getImageUrl()); ps.setString(9, p.getStatus().name()); if (ps.executeUpdate() > 0) { try (ResultSet k = ps.getGeneratedKeys()) { if (k.next()) p.setId(k.getLong(1)); } return true; } } catch (SQLException e) {} return false; }
    public boolean update(Product p) { try (Connection c = DBConnection.getConnection(); PreparedStatement ps = c.prepareStatement("UPDATE products SET category_id=?,name=?,brand=?,description=?,price=?,discount=?,stock=?,image_url=?,status=? WHERE id=?")) { ps.setInt(1, p.getCategoryId()); ps.setString(2, p.getName()); ps.setString(3, p.getBrand()); ps.setString(4, p.getDescription()); ps.setBigDecimal(5, p.getPrice()); ps.setBigDecimal(6, p.getDiscount()); ps.setInt(7, p.getStock()); ps.setString(8, p.getImageUrl()); ps.setString(9, p.getStatus().name()); ps.setLong(10, p.getId()); return ps.executeUpdate() > 0; } catch (SQLException e) {} return false; }
    public boolean delete(Long id) { try (Connection c = DBConnection.getConnection()) { try (PreparedStatement ch = c.prepareStatement("SELECT COUNT(*) FROM order_items WHERE product_id=?")) { ch.setLong(1, id); try (ResultSet r = ch.executeQuery()) { if (r.next() && r.getInt(1) > 0) { try (PreparedStatement d = c.prepareStatement("UPDATE products SET status='INACTIVE' WHERE id=?")) { d.setLong(1, id); return d.executeUpdate() > 0; } } } } try (PreparedStatement d = c.prepareStatement("DELETE FROM products WHERE id=?")) { d.setLong(1, id); return d.executeUpdate() > 0; } } catch (SQLException e) {} return false; }
    public int countTotalProducts() { try (Connection c = DBConnection.getConnection(); PreparedStatement p = c.prepareStatement("SELECT COUNT(*) FROM products"); ResultSet r = p.executeQuery()) { if (r.next()) return r.getInt(1); } catch (SQLException e) {} return 0; }
    private Product mapRow(ResultSet r) throws SQLException { Product p = new Product(); p.setId(r.getLong("id")); p.setCategoryId(r.getInt("category_id")); try { p.setCategoryName(r.getString("category_name")); } catch (SQLException e) {} p.setName(r.getString("name")); p.setBrand(r.getString("brand")); p.setDescription(r.getString("description")); p.setPrice(r.getBigDecimal("price")); p.setDiscount(r.getBigDecimal("discount")); p.setStock(r.getInt("stock")); p.setImageUrl(r.getString("image_url")); p.setStatus(Product.Status.valueOf(r.getString("status"))); p.setCreatedAt(r.getTimestamp("created_at")); try { p.setAverageRating(r.getDouble("avg_rating")); p.setReviewCount(r.getInt("rev_count")); } catch (SQLException e) {} return p; }
}
